//! Pure tests against tests/vectors.json (generated by game/scripts/gen-agent-vectors.mjs from the JavaScript twin):
//! token id, canonical state JSON, state hash, SVG, media data URI, media hash, title, description and extra must
//! match byte for byte; every invalid case must be rejected with the same error code as in JavaScript. Also checks the
//! judge playthrough's mint arguments (judge/<season>/mint-agent.json, written by scripts/judge-agent-args.mjs).

use crate::image::{metadata_parts, svg};
use crate::state::{hex, AgentState, SPEC};
use near_sdk::serde::Deserialize;
use near_sdk::serde_json::{self, Value};

const VECTORS: &str = include_str!("../tests/vectors.json");
const JUDGE_MINT: &str = include_str!("../judge/793f6c05e89839f2/mint-agent.json");
const JUDGE_STATE: &str = include_str!("../judge/793f6c05e89839f2/state.json");
const JUDGE_SVG: &str = include_str!("../judge/793f6c05e89839f2/card.svg");

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Metadata {
    title: String,
    description: String,
    media: String,
    media_hash: String,
    extra: String,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
#[serde(rename_all = "camelCase")]
struct AgentVector {
    input: AgentState,
    token_id: String,
    state_json: String,
    state_hash: String,
    svg: String,
    svg_sha256: String,
    metadata: Metadata,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Invalid {
    why: String,
    code: String,
    data: Value,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Vectors {
    spec: String,
    agents: Vec<AgentVector>,
    invalid: Vec<Invalid>,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct MintArgs {
    receiver_id: String,
    state: AgentState,
    state_hash: String,
}

fn vectors() -> Vectors {
    serde_json::from_str(VECTORS).expect("vectors.json parses")
}

#[test]
fn spec_matches() {
    let v = vectors();
    assert_eq!(v.spec, SPEC);
    assert!(v.agents.len() >= 6);
    assert!(v.invalid.len() >= 30);
}

#[test]
fn every_vector_validates_and_reproduces_token_id_json_and_hash() {
    for v in vectors().agents {
        v.input.validate().unwrap_or_else(|e| panic!("{}: {e}", v.token_id));
        assert_eq!(v.input.token_id(), v.token_id);
        assert_eq!(v.input.canonical_json(), v.state_json, "canonical json of {}", v.token_id);
        assert_eq!(v.input.state_hash(), v.state_hash, "state hash of {}", v.token_id);
        // the canonical JSON round-trips to the same state
        let back: AgentState = serde_json::from_str(&v.state_json).unwrap();
        assert_eq!(back, v.input);
    }
}

#[test]
fn every_vector_reproduces_the_svg_and_metadata() {
    use near_sdk::base64::Engine as _;
    for v in vectors().agents {
        let image = svg(&v.input);
        assert_eq!(image, v.svg, "svg of {}", v.token_id);
        assert_eq!(hex(&near_sdk::env::sha256(image.as_bytes())), v.svg_sha256, "svg hash of {}", v.token_id);
        let m = metadata_parts(&v.input);
        assert_eq!(m.title, v.metadata.title, "title of {}", v.token_id);
        assert_eq!(m.description, v.metadata.description, "description of {}", v.token_id);
        assert_eq!(m.media, v.metadata.media, "media of {}", v.token_id);
        assert_eq!(near_sdk::base64::engine::general_purpose::STANDARD.encode(&m.media_hash.0), v.metadata.media_hash, "media_hash of {}", v.token_id);
        assert_eq!(m.extra, v.metadata.extra, "extra of {}", v.token_id);
        assert_eq!(m.extra, v.state_json, "extra is the canonical state");
        assert_eq!(m.state_hash, v.state_hash);
    }
}

#[test]
fn every_invalid_vector_is_rejected_with_the_javascript_code() {
    for bad in vectors().invalid {
        let d: AgentState = serde_json::from_value(bad.data.clone()).unwrap_or_else(|e| panic!("{} does not deserialise: {e}", bad.why));
        match d.validate() {
            Ok(()) => panic!("accepted invalid case: {}", bad.why),
            Err(e) => assert!(e.starts_with(&format!("{}:", bad.code)), "{}: expected {}, got {e}", bad.why, bad.code),
        }
    }
}

#[test]
fn svg_is_well_formed_and_small() {
    for v in vectors().agents {
        let image = svg(&v.input);
        assert!(image.starts_with("<svg xmlns=\"http://www.w3.org/2000/svg\""));
        assert!(image.ends_with("</svg>"));
        assert!(image.len() < 8000, "svg of {} is {} bytes", v.token_id, image.len());
        assert!(image.contains(&format!("STATE {}", &v.state_hash[..16])));
        let drawn = (v.input.biography.remembered.len() + v.input.biography.forgotten.len()).min(12);
        assert!(image.matches("cy=\"236\"").count() >= drawn);
    }
}

#[test]
fn judge_mint_arguments_are_valid_and_their_hash_is_what_the_contract_computes() {
    let args: MintArgs = serde_json::from_str(JUDGE_MINT).expect("mint-agent.json parses");
    assert_eq!(args.receiver_id, "lambada_eth.testnet");
    args.state.validate().expect("the judge state validates");
    assert_eq!(args.state.token_id(), "793f6c05e89839f2-agent-iris");
    assert_eq!(args.state.canonical_json(), JUDGE_STATE, "state.json is the canonical JSON");
    assert_eq!(args.state.state_hash(), args.state_hash, "the declared hash is the one mint_agent recomputes");
    assert_eq!(args.state.schedule_root, "03dbd4587b5d54fc3a6d4befe19920ba66236de11e786baa0a8678305075769a", "the root committed on ftf-seasons.testnet");
    assert_eq!(svg(&args.state), JUDGE_SVG);
}
